#include "Halide.h"

// include common definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "symm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization, translated from the original C version.
 *
 * Original C signature:
 *   void init_array(int m, int n,
 *                   DATA_TYPE *alpha,
 *                   DATA_TYPE *beta,
 *                   DATA_TYPE C[M][N],
 *                   DATA_TYPE A[M][M],
 *                   DATA_TYPE B[M][N]);
 *
 * Mapping:
 *   - C[i][j] (MxN) -> Buffer C(j, i) with shape (n, m)
 *   - B[i][j] (MxN) -> Buffer B(j, i) with shape (n, m)
 *   - A[i][j] (MxM) -> Buffer A(j, i) with shape (m, m)
 */
static
void init_array(int m, int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    // Initialize C and B:
    //
    // C[i][j] = (DATA_TYPE)((i + j) % 100) / m;
    // B[i][j] = (DATA_TYPE)((n + i - j) % 100) / m;
    //
    // With our Buffer layout C(j, i), B(j, i):
    Func init_C("init_C"), init_B("init_B");

    init_C(j, i) = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    init_B(j, i) = cast<num_t>(((n + i - j) % 100)) / cast<int>(m);

    // Initialize A:
    //
    // for (i = 0; i < m; i++) {
    //   for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)((i + j) % 100) / m;
    //   for (j = i+1; j < m; j++)
    //       A[i][j] = -999;
    // }
    //
    // We store A[i][j] at A(j, i), and fill the "unused" upper part with -999.
    Func init_A("init_A");
    Expr lower_tri = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    Expr unused    = cast<num_t>(-999);
    init_A(j, i)   = select(j <= i, lower_tri, unused);

    // Simple but effective schedules for the initializations:
    //   - i is outer and parallel (independent rows),
    //   - j is inner and vectorized (contiguous in memory).
    const int init_vec = 8;

    init_C
        .parallel(i)
        .vectorize(j, init_vec);

    init_B
        .parallel(i)
        .vectorize(j, init_vec);

    init_A
        .parallel(i)
        .vectorize(j, init_vec);

    // Realize into the provided buffers
    init_C.realize(C);
    init_B.realize(B);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from symm.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C, B : MxN  -> (n, m) in Halide (dim 0 = column j, dim 1 = row i)
    //   A    : MxM  -> (m, m) in Halide (dim 0 = column j, dim 1 = row i)
    Halide::Buffer<num_t, 2> C(n, m);
    Halide::Buffer<num_t, 2> B(n, m);
    Halide::Buffer<num_t, 2> A(m, m);

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data
    init_array(m, n, &alpha, &beta, C, A, B);

    // Vars and reduction domain
    Var i("i"), j("j");
    // A is MxM stored as A(j, i); extent of dim(0) is m
    RDom k(0, A.dim(0).extent(), "k");

    // Main computational kernel in Halide.
    //
    // Original BLAS semantics:
    //   C := alpha * A * B + beta * C
    // with A symmetric, stored in its lower triangular part.
    //
    // Logical indices:
    //   - i: row index of A and C
    //   - j: column index of B and C
    //   - k: reduction index over inner dimension
    //
    // Buffer mapping:
    //   original A[i][k] -> A_param(k, i)
    //   original A[k][i] -> A_param(i, k)
    //   original B[k][j] -> B_param(j, k)
    //   original C[i][j] -> C_param(j, i)
    //
    // Symmetric logical view of A:
    //   A_sym(i, k) =
    //      (k <= i) ? A[i][k]  : A[k][i]
    // which in our Buffer coordinates is:
    //   A_sym(i, k) =
    //      (k <= i) ? A_param(k, i) : A_param(i, k)
    //
    Func symm("symm");

    // Base: beta * C
    symm(j, i) = Expr(beta) * C_param(j, i);

    // Symmetric access to A (only the stored lower triangle is used)
    Expr A_sym = select(k <= i, A_param(k, i), A_param(i, k));

    // Accumulate alpha * A_sym * B
    symm(j, i) += Expr(alpha) * A_sym * B_param(j, k);

    // ------------------------------------------------------------------
    // Scheduling for performance
    // ------------------------------------------------------------------
    //
    // We tile the (j, i) space to improve cache locality for C and B,
    // and split the reduction over k to improve reuse of A and B tiles
    // and to expose instruction-level parallelism.
    //
    // Layout recap:
    //   - C_param(j, i) and B_param(j, k) are contiguous in j
    //   - A_param(k, i) / A_param(i, k) are contiguous in k
    //
    // So we:
    //   - tile (j, i) so each tile of C and B fits into cache
    //   - parallelize over fused (j, i) tiles
    //   - keep j as the innermost dimension and vectorize it
    //   - split k into ko/ki to operate on k-tiles
    //   - unroll ki for ILP
    //
    const int tile_j = 64;   // columns of C/B per tile
    const int tile_i = 32;   // rows of C/A per tile
    const int tile_k = 32;   // k-depth per tile
    const int vec_j  = 8;    // SIMD width along contiguous j
    const int unroll_k = 4;  // unroll factor for inner k-loop

    Var jo("jo"), io("io"), jj("jj"), ii("ii");
    Var tile_index("tile_index");
    RVar ko("ko"), ki("ki");

    // Tile the (j, i) space and fuse tile indices for coarse-grain parallelism.
    //
    // After tile:
    //   j = jo * tile_j + jj
    //   i = io * tile_i + ii
    //
    // We then fuse (jo, io) into a single 'tile_index' and parallelize over it.
    symm
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i, TailStrategy::GuardWithIf)
        .fuse(jo, io, tile_index)
        // jj is innermost for contiguous accesses to C and B.
        .reorder(jj, ii, tile_index)
        .vectorize(jj, vec_j)
        .parallel(tile_index);

    // Schedule the reduction update:
    //
    // Desired loop structure (conceptual):
    //
    //   for tile_index (parallel):
    //     for ko over k-tiles:
    //       for ii in [0, tile_i):
    //         let i = ...
    //         for ki in [0, tile_k) (unrolled):
    //           let k = ...
    //           let a = A_sym(i, k);      # reused across jj
    //           for jj in [0, tile_j) (vectorized):
    //             let j = ...
    //             C(j,i) += alpha * a * B(j,k);
    //
    symm.update()
        .split(k, ko, ki, tile_k, TailStrategy::GuardWithIf)
        // Innermost to outermost: jj, ki, ii, ko, tile_index.
        .reorder(jj, ki, ii, ko, tile_index)
        .vectorize(jj, vec_j)
        .unroll(ki, unroll_k);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // JIT-compile the kernel
    symm.compile_jit();

    // Time the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination),
    // following the style of the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C(ii, jj) in C layout is C(jj, ii) in our Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
