    // Compute the final result at root.
    symm.compute_root();

    // ---------------------------
    // Pure definition scheduling
    // ---------------------------
    //
    // This computes symm(j,i) = beta * C_param(j,i).
    // We tile (j,i), fuse the tile indices, parallelize across tiles,
    // and vectorize across the inner j-part (ji).
    symm
        .tile(j, i, jo, io, ji, ii,
