        // Fuse tile coordinates for 2D tiling (cols x rows) into one
        // parallel dimension. Each tile writes a disjoint region of C.
        .fuse(jo, io, tile)
        // Loop order inside each tile:
        //   outer: tile
        //   mid  : ii (rows inside tile)
        //   inner: ji (cols inside tile, contiguous in memory)
        .reorder(ji, ii, tile)
        .vectorize(ji, vec_width)
        .parallel(tile);

    // ----------------------------
    // Update definition scheduling
    // ----------------------------
    //
    // This computes the reduction:
    //   symm(j,i) += alpha * A_sym(i,k) * B_param(j,k)
    //
    // We use the same (j,i) tiling/fusing as above, and additionally
