        .split(k, ko, ki, tile_k, TailStrategy::GuardWithIf)
        // Loop order inside each tile:
        //   outer: tile (parallel)
        //   then:  ko   (k-blocks)
        //          ii   (rows of C / A within tile)
        //          ki   (k within block)
        //          ji   (cols of C / B within tile, contiguous)
        //
        // This structure lets us:
        //   - Reuse A_sym(i,k) across all ji within the tile.
        //   - Stream B_param(j,k) and C_param(j,i) with unit stride in j.
        .reorder(ji, ki, ii, ko, tile)
        .vectorize(ji, vec_width)
        .unroll(ki, 4)   // small unroll factor for ILP within a k-tile
        .parallel(tile);

