    //   symm(j, i) += alpha * sum_k A_sym(i, k) * B_param(j, k)
    //
    Func symm("symm");

    // Base: beta * C
    symm(j, i) = Expr(beta) * C_param(j, i);

    // Symmetric access to A
    Expr A_sym = select(k <= i, A_param(k, i), A_param(i, k));

    // Accumulate alpha * A_sym * B
    symm(j, i) += Expr(alpha) * A_sym * B_param(j, k);

    // ------------------------------------------------------------------
    // Optimized schedule for SYMM:
    //
    //  - Tile in (j, i, k) to improve cache locality.
    //  - Parallelize across tiles in i (rows of C/A).
    //  - Vectorize along j (dim 0, contiguous in memory).
    //  - Block k (reduction) to improve reuse of A and B tiles.
    // ------------------------------------------------------------------

    // Get a reasonable vector width for the host
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tile sizes: chosen to be cache- and SIMD-friendly on typical x64.
    const int tile_j = 64;  // columns of C/B
    const int tile_i = 32;  // rows of C/A
    const int tile_k = 64;  // reduction dimension

    // Outer/inner vars for tiling
    Var jo("jo"), io("io"), ji("ji"), ii("ii");
    RVar ko("ko"), ki("ki");

    // Pure definition: symm(j, i) = beta * C(j, i)
    //
    // We want a loop nest of the form (conceptually):
    //   for io (row tiles, parallel):
    //     for jo (col tiles):
    //       for ii in [0, tile_i):
    //         for ji in [0, tile_j) (vectorized):
    //           symm(j, i) = beta * C(j, i)
    //
    symm
        // Tile over (j, i)
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i, TailStrategy::GuardWithIf)
        // Order loops from outermost to innermost: io, jo, ii, ji
        // (arguments are listed from innermost to outermost)
        .reorder(ji, ii, jo, io)
        // Vectorize along the contiguous j-dimension inside each tile
        .vectorize(ji, vec_width)
        // Parallelize across row tiles: each io-tile touches disjoint rows
        .parallel(io);

    // Update definition: symm(j, i) += alpha * sum_k A_sym(i, k) * B(j, k)
    //
    // Desired loop structure (conceptual):
    //
    //   for io (parallel over row tiles):
    //     for jo (column tiles):
    //       for ko (k-tiles):
    //         for ii in [0, tile_i):
    //           for ki in [0, tile_k):
    //             for ji in [0, tile_j) vectorized:
    //               symm(j, i) += alpha * A_sym(i, k) * B(j, k)
    //
    symm.update()
        // Tile spatial loops as above
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i, TailStrategy::GuardWithIf)
        // Block the reduction over k
        .split(k, ko, ki, tile_k, TailStrategy::GuardWithIf)
        // Reorder from innermost to outermost: ji, ki, ii, ko, jo, io
        //  -> outer: io (parallel), jo, ko, ii, ki, ji
        .reorder(ji, ki, ii, ko, jo, io)
        // Vectorize across ji (contiguous j)
        .vectorize(ji, vec_width)
        // Parallelize across row tiles also in the update
        .parallel(io);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // JIT-compile the kernel for the chosen target
    symm.compile_jit(target);

    // Time the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination),
    // following the style of the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C(ii, jj) in C layout is C(jj, ii) in our Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
