    // Initialization schedule
    // -----------------------------
    // All three initializations are embarrassingly parallel and operate
    // over the same rectangular domains. We parallelize in the slower
    // dimension (rows, i) and vectorize along the contiguous dimension (j).
    const int vec = 8;  // reasonable SIMD width on modern x86; safe even if scalarized

    init_C
        .parallel(i)
        .vectorize(j, vec);

    init_B
        .parallel(i)
        .vectorize(j, vec);

    init_A
        .parallel(i)
        .vectorize(j, vec);

    // Realize into the provided buffers
    init_C.realize(C);
    init_B.realize(B);
    init_A.realize(A);
