    // Symmetric access to A
    Expr A_sym = select(k <= i, A_param(k, i), A_param(i, k));

    // Accumulate alpha * A_sym * B
    symm(j, i) += Expr(alpha) * A_sym * B_param(j, k);

    // ------------------------------------------------------------------
    // Optimized schedule for SYMM
    //
    // Goal:
    //   - good cache locality via 3D tiling over (i, j, k),
    //   - exploit 32-core parallelism over tiles of rows (i),
    //   - SIMD-vectorize along j (contiguous dimension in C and B),
    //   - unroll over k for extra ILP.
    //
    // Coordinate mapping reminder:
    //   - symm(j, i)   : j indexes columns (0..n-1), i indexes rows (0..m-1)
    //   - C_param(j,i) : layout C[i][j] at C(j,i)
    //   - B_param(j,k) : layout B[k][j] at B(j,k)
    //   - A_param(j,i) : layout A[i][j] at A(j,i), lower triangle filled
    //
