    const int tile_j = 64;   // cols per tile
    const int tile_k = 32;   // k-slab size
    const int vec_j  = 8;    // SIMD width along j (safe default)

    // Tile variables for the row/col space
    Var io("io"), jo("jo"), ii("ii"), jj("jj");

    // Tile variables for the reduction domain
    RVar ko("ko"), ki("ki");

    // Tiling and scheduling of the pure definition (beta * C)
    //
    // Conceptual pure loop nest after tiling:
    //   for io (tiles in i)   [parallel]
    //     for jo (tiles in j)
    //       for ii in [0, tile_i)
    //         for jj in [0, tile_j) [vectorized]
    //           symm(jj + jo*tile_j, ii + io*tile_i) = beta * C(...)
    symm
        .tile(j, i,  // tile over (j, i)
              jo, io,
              jj, ii,
              tile_j, tile_i)
        // Reorder so that within each tile jj (inner j) is innermost
        // and io (tile index over rows) is outermost:
        .reorder(jj, ii, jo, io)
        // Parallelize over row tiles: each io processes a disjoint band
        // of rows of C, so no write conflicts.
        .parallel(io)
        // Vectorize along jj (contiguous j-dimension in C and B).
        .vectorize(jj, vec_j);

    // Tiling and scheduling of the reduction update
    //
    // We add an additional split of the reduction domain k into
    //   k = ko * tile_k + ki
    // to get 3D blocking (i,j,k). The conceptual loop nest becomes:
    //
    //   for io (row tiles) [parallel]
    //     for jo (col tiles)
    //       for ko (k tiles)
    //         for ii in [0, tile_i)
    //           for ki in [0, tile_k)
    //             for jj in [0, tile_j) [vectorized]
    //               symm(j,i) += alpha * A_sym(i,k) * B(j,k)
    //
    symm.update()
        // Tile over (j, i) as above
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i)
        // Split the reduction domain k into coarse and fine pieces
        .split(k, ko, ki, tile_k)
        // Reorder loops (arguments listed from innermost to outermost):
        //   innermost:  jj (vectorized over j)
        //   then:       ki (inner k within a k-tile)
        //   then:       ii (rows within an i-tile)
        //   then:       ko (k-tile index)
        //   then:       jo (col-tile index)
        //   outermost:  io (row-tile index, parallel)
        .reorder(jj, ki, ii, ko, jo, io)
        // Parallelize across row tiles.
        .parallel(io)
        // Vectorize across contiguous jj.
        .vectorize(jj, vec_j)
        // Unroll a small number of iterations in the fine k-loop to
        // expose instruction-level parallelism without overusing
        // registers; 4 is a good generic choice.
        .unroll(ki, 4);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // JIT-compile the kernel
    symm.compile_jit();

    // Time the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination),
    // following the style of the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C(ii, jj) in C layout is C(jj, ii) in our Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
